import{_ as e,o,c as a,a2 as n}from"./chunks/framework.Dhf_H6O0.js";const s="/mbit-mcpo-proxy-download/guide/images/telecontext-configurator.png",p=JSON.parse('{"title":"Telecontext (Telekom)","description":"","frontmatter":{},"headers":[],"relativePath":"catalog/telecontext.md","filePath":"catalog/telecontext.md"}'),r={name:"catalog/telecontext.md"};function i(l,t,c,d,g,h){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="telecontext-telekom" tabindex="-1">Telecontext (Telekom) <a class="header-anchor" href="#telecontext-telekom" aria-label="Permalink to &quot;Telecontext (Telekom)&quot;">​</a></h1><p>Telekom Telecontext is an enterprise MCP server that gives your AI tools access to <strong>Jira</strong>, <strong>GitLab</strong>, <strong>Confluence</strong>, and more — all through a single connection with OAuth sign-in.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A <strong>Telekom Teleconsole</strong> account with the services you want to use activated.</li><li>Complete the <strong>Teleconsole Authorization services setup</strong> for each service (Jira, GitLab, etc.) before adding Telecontext.</li></ul><div class="warning custom-block"><p class="custom-block-title">Set up Teleconsole first</p><p>Telecontext connects to your enterprise tools through Teleconsole. If a service isn&#39;t authorized in Teleconsole, those tools won&#39;t work even if they&#39;re selected here.</p></div><h2 id="step-1-add-from-catalog" tabindex="-1">Step 1: Add from catalog <a class="header-anchor" href="#step-1-add-from-catalog" aria-label="Permalink to &quot;Step 1: Add from catalog&quot;">​</a></h2><ol><li>Click <strong>Catalog</strong> in the sidebar.</li><li>Find <strong>Telekom Telecontext</strong> (it has the <code>ENTERPRISE</code> tag).</li><li>Click the <strong>+</strong> button.</li><li>The <strong>Telecontext configurator</strong> opens.</li></ol><h2 id="step-2-choose-categories-and-tools" tabindex="-1">Step 2: Choose categories and tools <a class="header-anchor" href="#step-2-choose-categories-and-tools" aria-label="Permalink to &quot;Step 2: Choose categories and tools&quot;">​</a></h2><p><img src="'+s+'" alt="Telecontext configurator showing categories and tools"></p><p>The configurator shows all available <strong>categories</strong> of tools. Each category contains multiple individual tools. There are 11 categories with over 100 tools in total.</p><h3 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Category</th><th>Tools</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Knowledge</strong></td><td>1</td><td>Query Deutsche Telekom IT&#39;s internal knowledge base and documentation through AI-powered chatbots.</td></tr><tr><td><strong>Tardis</strong></td><td>3</td><td>Search and inspect APIs on the TARDIS API platform — find APIs, get details, and retrieve OpenAPI specs.</td></tr><tr><td><strong>Chatbot Factory</strong></td><td>2</td><td>List and query Telekom chatbots you have access to through the Chatbot Factory.</td></tr><tr><td><strong>PSA</strong></td><td>3</td><td>Browse the Privacy &amp; Security Assessment (PSA) document library — list subject areas, requirement documents, and individual security/data privacy requirements.</td></tr><tr><td><strong>GitLab</strong></td><td>50</td><td>Full GitLab integration: repositories, branches, commits, issues, merge requests (including discussions, approvals, merging), epics, CI/CD pipelines and jobs, projects, groups, wikis, and global search. Includes both READ and WRITE tools.</td></tr><tr><td><strong>Jira</strong></td><td>33</td><td>Full Jira integration: create/update/search/delete issues, manage sprints and boards, handle worklogs, link issues and epics, manage versions, transition issue status, and more. Includes both READ and WRITE tools.</td></tr><tr><td><strong>Raccoon</strong></td><td>6</td><td>Monitoring and observability: execute PromQL instant and range queries against Raccoon/VictoriaMetrics, list metrics, labels, and check server status.</td></tr><tr><td><strong>LeanIX</strong></td><td>1</td><td>Enterprise architecture management: retrieve factsheet information from LeanIX by ID, name, or email.</td></tr><tr><td><strong>Confluence</strong></td><td>12</td><td>Full Confluence integration: read and create pages, manage comments and labels, search content and users, view page statistics, and navigate page hierarchies. Includes both READ and WRITE tools.</td></tr><tr><td><strong>Feedback</strong></td><td>2</td><td>Submit and analyze feedback for agent performance.</td></tr><tr><td><strong>Meta</strong></td><td>3</td><td>Utility tools: search available tools by name, and call any tool by name with parameters (useful for dynamic tool discovery).</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Services require Teleconsole authorization</p><p>Each category corresponds to a Teleconsole service. You must complete the <strong>Teleconsole Authorization services setup</strong> for a category before its tools will work. For example, to use GitLab tools, authorize the GitLab service in Teleconsole first.</p></div><h3 id="selecting-tools" tabindex="-1">Selecting tools <a class="header-anchor" href="#selecting-tools" aria-label="Permalink to &quot;Selecting tools&quot;">​</a></h3><ul><li><strong>Check a category</strong> to include all its tools.</li><li><strong>Expand a category</strong> (click the arrow) to see individual tools and select only the ones you need.</li><li>Each tool is labeled <strong>READ</strong> (non-mutating, just retrieves data) or <strong>WRITE</strong> (can modify remote state — create issues, merge requests, etc.).</li></ul><div class="tip custom-block"><p class="custom-block-title">Keep it focused</p><p>The more tools you enable, the more context your AI assistant needs to process. If you enable more than <strong>50 tools</strong>, a warning appears:</p><blockquote><p>&quot;Tool count warning — Enabling more than 50 tools may impact performance and consume more context space. Consider selecting only the tools you need for your workflow.&quot;</p></blockquote><p>A good starting point: enable <strong>Knowledge</strong> + <strong>Jira</strong> + <strong>Confluence</strong> for general enterprise use, or <strong>GitLab</strong> alone for development workflows. You can always come back and add more categories.</p></div><h3 id="read-only-mode" tabindex="-1">Read-only mode <a class="header-anchor" href="#read-only-mode" aria-label="Permalink to &quot;Read-only mode&quot;">​</a></h3><p>The configurator shows a hint about <strong>read-only mode</strong> at the top. The URL it generates is what MCPBehindIT uses to configure the connection.</p><h2 id="step-3-save" tabindex="-1">Step 3: Save <a class="header-anchor" href="#step-3-save" aria-label="Permalink to &quot;Step 3: Save&quot;">​</a></h2><p>Click <strong>Save</strong> (or the confirm button). The server is added to your <strong>Servers</strong> list with the name <code>telecontext</code>.</p><h2 id="step-4-start-the-gateway" tabindex="-1">Step 4: Start the gateway <a class="header-anchor" href="#step-4-start-the-gateway" aria-label="Permalink to &quot;Step 4: Start the gateway&quot;">​</a></h2><ol><li>Go to <strong>Home</strong>.</li><li>Click <strong>Start</strong> (or <strong>Apply &amp; Restart</strong> if the gateway is already running).</li><li>Watch the progress log as the gateway starts.</li></ol><h2 id="step-5-oauth-sign-in" tabindex="-1">Step 5: OAuth sign-in <a class="header-anchor" href="#step-5-oauth-sign-in" aria-label="Permalink to &quot;Step 5: OAuth sign-in&quot;">​</a></h2><p>After the gateway starts, Telecontext requires you to sign in with your Telekom account.</p><p><strong>What happens:</strong></p><ol><li>The gateway connects to Telecontext and receives an OAuth authorization URL.</li><li>MCPBehindIT detects this URL in the container logs.</li><li>A <strong>notification toast</strong> appears at the bottom-right of the app window: <ul><li>Title: <strong>&quot;OAuth sign-in required&quot;</strong></li><li>Description: An MCP server needs you to sign in.</li><li>Buttons: <strong>Open in browser</strong> and <strong>Copy URL</strong></li></ul></li><li>Click <strong>Open in browser</strong>. Your default browser opens to the Telekom sign-in page.</li><li>Sign in with your Teleconsole credentials.</li><li>After successful authentication, the browser shows a confirmation. Return to MCPBehindIT.</li></ol><div class="tip custom-block"><p class="custom-block-title">Browser didn&#39;t open?</p><p>Click <strong>Copy URL</strong> on the toast and paste it into your browser manually.</p></div><h2 id="step-6-verify-the-connection" tabindex="-1">Step 6: Verify the connection <a class="header-anchor" href="#step-6-verify-the-connection" aria-label="Permalink to &quot;Step 6: Verify the connection&quot;">​</a></h2><ol><li>Go to <strong>Logs</strong> and look for:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Successfully connected to &#39;telecontext&#39;</span></span></code></pre></div></li><li>Go to <strong>Home</strong> → <strong>Clients</strong> tab. You should see the <code>telecontext</code> server row with its URLs.</li><li>Copy the <strong>OpenAPI</strong> URL and paste it into your AI tool to start using Telecontext.</li></ol><h2 id="editing-telecontext" tabindex="-1">Editing Telecontext <a class="header-anchor" href="#editing-telecontext" aria-label="Permalink to &quot;Editing Telecontext&quot;">​</a></h2><p>To change which categories or tools are active:</p><ol><li>Go to <strong>Servers</strong>.</li><li>Click <strong>Edit</strong> on the <code>telecontext</code> row.</li><li>The configurator reopens with your current selection.</li><li>Make changes and save.</li><li><strong>Apply &amp; Restart</strong> on Home.</li></ol><h2 id="disabling-telecontext" tabindex="-1">Disabling Telecontext <a class="header-anchor" href="#disabling-telecontext" aria-label="Permalink to &quot;Disabling Telecontext&quot;">​</a></h2><p>Click <strong>Disable</strong> on the <code>telecontext</code> row in Servers if you want to temporarily exclude it without losing your configuration. <strong>Apply &amp; Restart</strong> on Home.</p><h2 id="oauth-re-authentication" tabindex="-1">OAuth re-authentication <a class="header-anchor" href="#oauth-re-authentication" aria-label="Permalink to &quot;OAuth re-authentication&quot;">​</a></h2><p>OAuth tokens expire. When they do, the gateway automatically requests a new authorization URL, and the OAuth toast appears again. Just sign in again — your tool selection is not affected.</p>',36)])])}const m=e(r,[["render",i]]);export{p as __pageData,m as default};
